sql.where:
p.deleted = 0

    AND p.production_order_no = #{productionOrderNo}


    AND p.assembly_material_no = #{assemblyMaterialNo}


    AND p.main_material_desc = #{mainMaterialDesc}


    AND p.scheduled_date >= #{scheduledDateStart}


    AND p.scheduled_date <= #{scheduledDateEnd}


    AND p.scheduled_quantity = #{scheduledQuantity}


    AND p.production_workshop = #{productionWorkshop}


    AND p.create_time >= #{createTimeStart}


    AND p.create_time <= #{createTimeEnd}

mapper.select:
WITH order_base AS ( SELECT order_no, MAX(quantity) AS plan_qty, MAX(completed_quantity) AS completed_qty, MAX(transfer_order) AS transfer_order, SUM(purchase_required_qty) AS total_required_qty, COUNT(DISTINCT CASE WHEN open_order_quantity > 0 THEN purchase_material END) AS shortage_part_count FROM aps_matching_result WHERE deleted = 0
AND schedule_time >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND schedule_time < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND workshop = #{workshop}
AND supplier_name = #{supplier}
AND create_time >= (SELECT TRUNC(MAX(create_time)) FROM aps_matching_result WHERE deleted = 0) AND create_time < (SELECT TRUNC(MAX(create_time)) + 1 FROM aps_matching_result WHERE deleted = 0)
GROUP BY order_no ), order_flag AS ( SELECT order_no, plan_qty, completed_qty, total_required_qty, CASE WHEN shortage_part_count > 0 THEN 1 ELSE 0 END AS has_shortage, CASE WHEN transfer_order >= plan_qty THEN 1 ELSE 0 END AS is_transfer_completed FROM order_base ), total_req AS ( SELECT NVL(SUM(purchase_required_qty), 0) AS total_required_qty FROM aps_matching_result WHERE deleted = 0
AND schedule_time >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND schedule_time < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND workshop = #{workshop}
AND supplier_name = #{supplier}
AND create_time >= (SELECT TRUNC(MAX(create_time)) FROM aps_matching_result WHERE deleted = 0) AND create_time < (SELECT TRUNC(MAX(create_time)) + 1 FROM aps_matching_result WHERE deleted = 0)
), completed_shortage AS ( SELECT NVL(SUM(r.open_order_quantity), 0) AS completed_shortage_qty FROM aps_matching_result r WHERE r.deleted = 0 AND r.open_order_quantity > 0 AND EXISTS ( SELECT 1 FROM order_flag f WHERE f.order_no = r.order_no AND f.is_transfer_completed = 1 AND f.has_shortage = 1 )
AND r.schedule_time >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND r.schedule_time < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND r.workshop = #{workshop}
AND r.supplier_name = #{supplier}
AND r.create_time >= (SELECT TRUNC(MAX(create_time)) FROM aps_matching_result WHERE deleted = 0) AND r.create_time < (SELECT TRUNC(MAX(create_time)) + 1 FROM aps_matching_result WHERE deleted = 0)
) SELECT (SELECT COUNT(order_no) FROM order_flag) AS totalOrders, (SELECT NVL(SUM(plan_qty), 0) FROM order_flag) AS totalPlanQty, (SELECT NVL(SUM(completed_qty), 0) FROM order_flag) AS totalCompletedQty, CASE WHEN (SELECT SUM(plan_qty) FROM order_flag) = 0 THEN 0 ELSE ROUND((SELECT SUM(completed_qty) FROM order_flag) / (SELECT SUM(plan_qty) FROM order_flag) * 100, 2) END AS completionRate, (SELECT COUNT(CASE WHEN has_shortage = 1 THEN 1 END) FROM order_flag) AS shortageOrders, (SELECT total_required_qty FROM total_req) AS totalRequiredQty, (SELECT completed_shortage_qty FROM completed_shortage) AS completedShortageQty, (SELECT CASE WHEN COUNT(order_no) = 0 THEN 0 ELSE ROUND((1 - COUNT(CASE WHEN has_shortage = 1 THEN 1 END) / COUNT(order_no)) * 100, 2) END FROM order_flag) AS kitRate, TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS') AS lastUpdateTime FROM DUAL

WITH order_base AS ( SELECT order_no, MAX(quantity) AS plan_qty, MAX(completed_quantity) AS completed_qty, MAX(transfer_order) AS transfer_order, SUM(purchase_required_qty) AS total_required_qty, COUNT(DISTINCT CASE WHEN open_order_quantity > 0 THEN purchase_material END) AS shortage_part_count FROM aps_matching_result WHERE deleted = 0
AND schedule_time >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND schedule_time < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND workshop = #{workshop}
AND supplier_name = #{supplier}
AND create_time >= TO_DATE(#{createDate}, 'YYYY-MM-DD') AND create_time < TO_DATE(#{createDate}, 'YYYY-MM-DD') + 1 GROUP BY order_no ), order_flag AS ( SELECT order_no, plan_qty, completed_qty, total_required_qty, CASE WHEN shortage_part_count > 0 THEN 1 ELSE 0 END AS has_shortage, CASE WHEN transfer_order >= plan_qty THEN 1 ELSE 0 END AS is_transfer_completed FROM order_base ), total_req AS ( SELECT NVL(SUM(purchase_required_qty), 0) AS total_required_qty FROM aps_matching_result WHERE deleted = 0
AND schedule_time >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND schedule_time < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND workshop = #{workshop}
AND supplier_name = #{supplier}
AND create_time >= TO_DATE(#{createDate}, 'YYYY-MM-DD') AND create_time < TO_DATE(#{createDate}, 'YYYY-MM-DD') + 1 ), completed_shortage AS ( SELECT NVL(SUM(r.open_order_quantity), 0) AS completed_shortage_qty FROM aps_matching_result r WHERE r.deleted = 0 AND r.open_order_quantity > 0 AND EXISTS ( SELECT 1 FROM order_flag f WHERE f.order_no = r.order_no AND f.is_transfer_completed = 1 AND f.has_shortage = 1 )
AND r.schedule_time >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND r.schedule_time < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND r.workshop = #{workshop}
AND r.supplier_name = #{supplier}
AND r.create_time >= TO_DATE(#{createDate}, 'YYYY-MM-DD') AND r.create_time < TO_DATE(#{createDate}, 'YYYY-MM-DD') + 1 ) SELECT (SELECT COUNT(order_no) FROM order_flag) AS totalOrders, (SELECT NVL(SUM(plan_qty), 0) FROM order_flag) AS totalPlanQty, (SELECT NVL(SUM(completed_qty), 0) FROM order_flag) AS totalCompletedQty, CASE WHEN (SELECT SUM(plan_qty) FROM order_flag) = 0 THEN 0 ELSE ROUND((SELECT SUM(completed_qty) FROM order_flag) / (SELECT SUM(plan_qty) FROM order_flag) * 100, 2) END AS completionRate, (SELECT COUNT(CASE WHEN has_shortage = 1 THEN 1 END) FROM order_flag) AS shortageOrders, (SELECT total_required_qty FROM total_req) AS totalRequiredQty, (SELECT completed_shortage_qty FROM completed_shortage) AS completedShortageQty, (SELECT CASE WHEN COUNT(order_no) = 0 THEN 0 ELSE ROUND((1 - COUNT(CASE WHEN has_shortage = 1 THEN 1 END) / COUNT(order_no)) * 100, 2) END FROM order_flag) AS kitRate, TO_CHAR(TO_DATE(#{createDate}, 'YYYY-MM-DD'), 'YYYY-MM-DD HH24:MI:SS') AS lastUpdateTime FROM DUAL

SELECT COUNT(*) FROM ( SELECT order_no FROM aps_matching_result WHERE deleted = 0
AND schedule_time >= TO_DATE(#{req.startDate}, 'YYYY-MM-DD HH24:MI:SS')
AND schedule_time < TO_DATE(#{req.endDate}, 'YYYY-MM-DD HH24:MI:SS') + 1
AND workshop = #{req.workshop}
AND supplier_name = #{req.supplier}
AND order_no IN (SELECT DISTINCT order_no FROM aps_matching_result WHERE purchase_material = #{req.materialCode} OR material_code = #{req.materialCode})
AND create_time >= (SELECT TRUNC(MAX(create_time)) FROM aps_matching_result WHERE deleted = 0) AND create_time < (SELECT TRUNC(MAX(create_time)) + 1 FROM aps_matching_result WHERE deleted = 0)
GROUP BY order_no
HAVING COUNT(CASE WHEN open_order_quantity > 0 THEN 1 END) > 0
)
